Aşağıdaki `main` fonksiyonunun en belirgin yapısal problemi nedir?

```c
int main(void) {
    int d[100], n = 0, t = 0;
    while (scanf("%d", &d[n]) == 1) n++;
    for (int i = 0; i < n; i++) t += d[i];
    for (int i = 0; i < n - 1; i++)
        for (int j = 0; j < n - 1 - i; j++)
            if (d[j] > d[j+1]) { int x = d[j]; d[j] = d[j+1]; d[j+1] = x; }
    printf("%d %.2f %d\n", n, (double)t / n, d[n/2]);
    return 0;
}
```

questions.explain:
```c
#include <stdio.h>

int tekAdedi(const int d[], int n) {
    int say = 0;
    for (int i = 0; i < n; i++)
        if (d[i] % 2 != 0) say++;
    return say;
}

int tekToplami(const int d[], int n) {
    int t = 0;
    for (int i = 0; i < n; i++)
        if (d[i] % 2 != 0) t += d[i];
    return t;
}

int tekOrtalamasi(const int d[], int n, double *sonuc) {
    int adet = tekAdedi(d, n);
    if (adet == 0) return 0;               /* basarisiz */
    *sonuc = (double)tekToplami(d, n) / adet;
    return 1;                              /* basarili */
}

int main(void) {
    int a[7] = {4, 7, 1, 9, 4, 2, 3};
    double ort;

    if (tekOrtalamasi(a, 7, &ort))
        printf("Tek sayilarin ortalamasi: %.2f\n", ort);   /* 5.00 */
    else
        printf("Dizide tek sayi yok\n");
    return 0;
}
```

Dikkat edilecekler: (1) `tekOrtalamasi` başarı/başarısızlık bilgisini `return` ile, sonucu işaretçi parametreyle döndürüyor — böylece 'tek sayı yok' durumu sıfıra bölmeye dönüşmüyor. (2) Hiçbir hesap fonksiyonunda `printf` yok; sunum `main`in işi. (3) Diziler `const` — fonksiyonların veriyi bozmayacağı imzadan okunuyor. Örnekte tekler 7, 1, 9, 3 → toplam 20, adet 4, ortalama 5.00.

