```c
#include <stdio.h>
#include <stddef.h>

int *ilkNegatif(int *d, int n) {
    for (int *p = d; p < d + n; p++)
        if (*p < 0) return p;
    return NULL;
}

const int *ilkNegatifSabit(const int *d, int n) {
    for (const int *p = d; p < d + n; p++)
        if (*p < 0) return p;
    return NULL;
}

int main(void) {
    int a[5] = {4, 7, -3, 9, -1};

    int *p = ilkNegatif(a, 5);
    if (p != NULL) {
        printf("indeks=%d deger=%d\n", (int)(p - a), *p);  /* indeks=2 deger=-3 */
        *p = 0;                   /* adres dondugu icin duzeltme de yapabiliriz */
    }
    printf("%d\n", a[2]);        /* 0 */
    return 0;
}
```

İndeks yerine adres döndürmenin avantajı, `p - d` ile indeksi zaten hesaplayabilmeniz ve bulunan elemanı doğrudan değiştirebilmenizdir. `const` sürümünde dönüş tipi `int *` olsaydı, fonksiyon 'değiştirmem' sözü verdiği bir veriye yazma izni veren bir kapı açardı — `const` garantisi kaçırılırdı. Bu yüzden C kütüphanesinde `strchr` gibi fonksiyonların C sürümü bu kısıtı gevşetse de, kendi kodunuzda `const` girdi → `const` çıktı kuralına uyun.

