#include <stdio.h>

typedef struct {
    int x, y;
} Nokta;

void tasi(Nokta n) {
    n.x += 10;
    n.y += 10;
}

void tasiP(Nokta *n) {
    n->x += 10;
    n->y += 10;
}

int main(void) {
    Nokta a = {1, 2};
    Nokta b = a;

    b.x = 99;
    tasi(a);
    printf("%d %d %d\n", a.x, a.y, b.x);

    tasiP(&a);
    printf("%d %d\n", a.x, a.y);
    return 0;
}

#include <stdio.h>

typedef struct { int gun, ay, yil; } Tarih;

typedef struct {
    char  ad[20];
    Tarih dogum;
} Kisi;

int yas(Kisi k, Tarih bugun) {
    int y = bugun.yil - k.dogum.yil;
    if (bugun.ay < k.dogum.ay ||
        (bugun.ay == k.dogum.ay && bugun.gun < k.dogum.gun))
        y--;
    return y;
}

int main(void) {
    Kisi k = {"Zeynep", {15, 9, 2004}};
    Tarih bugun = {8, 9, 2025};

    printf("%d\n", yas(k, bugun));
    bugun.gun = 20;
    printf("%d\n", yas(k, bugun));
    return 0;
}

