```c
#include <stdio.h>
#include <stddef.h>

typedef struct {
    char   ad[20];
    int    no;
    double vize, final;
} Ogrenci;

double ortalama(const Ogrenci *o) {
    return 0.4 * o->vize + 0.6 * o->final;
}

const Ogrenci *enIyi(const Ogrenci d[], int n) {
    if (d == NULL || n <= 0) return NULL;        /* guard clause */

    const Ogrenci *en = &d[0];
    for (int i = 1; i < n; i++)
        if (ortalama(&d[i]) > ortalama(en)) en = &d[i];
    return en;
}

int main(void) {
    Ogrenci s[3] = {
        {"Ali",   101, 60, 70},
        {"Ayse",  102, 90, 80},
        {"Can",   103, 50, 95}
    };

    const Ogrenci *e = enIyi(s, 3);
    if (e != NULL)
        printf("%s %d %.2f\n", e->ad, e->no, ortalama(e));
    /* Ali 66.00, Ayse 84.00, Can 77.00  -> Ayse 102 84.00 */
    return 0;
}
```

Üç kritik nokta: (1) Aday `&d[0]` ile başlatılır; 0 ile başlatmak tüm ortalamalar negatif olsaydı yanlış sonuç verirdi (bu örnekte olmasa da alışkanlık önemlidir). (2) İndeks yerine **adres** döndürmek, çağıranın hem alanlara hem de konuma erişmesini sağlar (`e - s` indeksi verir). (3) Girdi `const` olduğu için dönüş tipi de `const Ogrenci *`tir — `const` garantisi kaçırılmaz. Ortalamalar: Ali 0.4×60+0.6×70 = 66, Ayşe 0.4×90+0.6×80 = 84, Can 0.4×50+0.6×95 = 77.

