```c
#include <stdio.h>

typedef struct {
    int    no;
    char   ad[20];
    double notu;
} Ogrenci;

int kaydet(const char *dosya, const Ogrenci d[], int n) {
    FILE *f = fopen(dosya, "wb");
    if (f == NULL) return 0;

    size_t yazilan = fwrite(d, sizeof(Ogrenci), (size_t)n, f);
    fclose(f);
    return yazilan == (size_t)n;
}

/* Numarasi eslesen kaydin notunu yerinde gunceller. */
int notGuncelle(const char *dosya, int no, double yeniNot) {
    FILE *f = fopen(dosya, "r+b");     /* icerigi KORUYARAK oku+yaz */
    if (f == NULL) return 0;

    Ogrenci o;
    long indeks = 0;
    int bulundu = 0;

    while (fread(&o, sizeof(o), 1, f) == 1) {
        if (o.no == no) {
            o.notu = yeniNot;
            /* okuma sonrasi konum bir kayit ilerledi: geri sar */
            fseek(f, indeks * (long)sizeof(o), SEEK_SET);
            bulundu = (fwrite(&o, sizeof(o), 1, f) == 1);
            break;
        }
        indeks++;
    }

    fclose(f);
    return bulundu;
}

int main(void) {
    Ogrenci s[3] = {
        {101, "Ali",  55.0},
        {102, "Ayse", 70.0},
        {103, "Can",  91.5}
    };

    if (!kaydet("ogrenci.dat", s, 3)) { printf("Yazma hatasi\n"); return 1; }
    if (!notGuncelle("ogrenci.dat", 102, 88.0)) { printf("Bulunamadi\n"); return 1; }

    FILE *f = fopen("ogrenci.dat", "rb");
    if (f == NULL) return 1;
    Ogrenci o;
    while (fread(&o, sizeof(o), 1, f) == 1)
        printf("%d %s %.1f\n", o.no, o.ad, o.notu);
    fclose(f);
    /* 101 Ali 55.0 / 102 Ayse 88.0 / 103 Can 91.5 */
    return 0;
}
```

Yapılan kontroller: (1) Her `fopen` sonrası `NULL` kontrolü — dosya yoksa veya izin yoksa program çökmez, hata döndürür. (2) `fread`/`fwrite` dönüş değerleri eleman sayısıyla karşılaştırılır; kısmi okuma sessizce geçilmez. (3) Güncellemede kritik nokta `fseek`tir: `fread` konumu bir kayıt ileri taşıdığı için, yazmadan önce kaydın başına geri sarmak gerekir; bu yapılmazsa **bir sonraki kaydın üzerine** yazılır. (4) `"r+b"` kipi seçilmiştir; `"wb"` dosyayı sıfırlar, `"ab"` ise yalnızca sona ekler.

