```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Dugum {
    int veri;
    struct Dugum *sonraki;
} Dugum;

Dugum *hepsiniSil(Dugum *bas, int v) {
    /* 1) Bastaki ardisik eslesmeleri temizle */
    while (bas != NULL && bas->veri == v) {
        Dugum *t = bas;
        bas = bas->sonraki;
        free(t);
    }

    /* 2) Ortadaki ve sondaki eslesmeler */
    Dugum *p = bas;
    while (p != NULL && p->sonraki != NULL) {
        if (p->sonraki->veri == v) {
            Dugum *t = p->sonraki;
            p->sonraki = t->sonraki;   /* once zinciri onar */
            free(t);                   /* sonra serbest birak */
            /* p ILERLETILMEZ: yeni p->sonraki de eslesebilir */
        } else {
            p = p->sonraki;
        }
    }
    return bas;
}

int main(void) {
    Dugum *bas = NULL;
    int v[7] = {7, 7, 3, 7, 7, 5, 7};   /* liste bu sirayla kurulacak */
    for (int i = 6; i >= 0; i--) {
        Dugum *y = malloc(sizeof(*y));
        if (y == NULL) return 1;
        y->veri = v[i];
        y->sonraki = bas;
        bas = y;
    }

    bas = hepsiniSil(bas, 7);
    for (Dugum *p = bas; p != NULL; p = p->sonraki)
        printf("%d%s", p->veri, p->sonraki ? " " : "\n");   /* 3 5 */

    while (bas != NULL) { Dugum *t = bas; bas = bas->sonraki; free(t); }
    return 0;
}
```

İki kritik nokta: (1) **Baştaki eşleşmeler** ayrı bir döngü ister, çünkü onların bir 'öncekisi' yoktur; baş işaretçisinin kendisi güncellenmelidir. Tek `if` yazmak, listenin başında art arda iki eşleşme varsa ikincisini kaçırır. (2) **Silmeden sonra `p` ilerletilmez**: `p->sonraki` zaten bir sonraki düğüme kaydığı için ilerletirseniz ardışık eşleşmelerden birini atlarsınız. Örnekte 7,7,3,7,7,5,7 listesinden tüm 7'ler silinir ve geriye **3 5** kalır. Ayrıca her `free` çağrısından önce adres geçici bir değişkende saklanır; bu olmadan zincirin kalanına erişim kaybedilir.

topics.notes:
## İki disiplin: LIFO ve FIFO

| | Yığın (stack) | Kuyruk (queue) |
|---|---|---|
| Kural | **LIFO** — son giren ilk çıkar | **FIFO** — ilk giren ilk çıkar |
| Ekleme | `push` — tepeye | `enqueue` — sona |
| Çıkarma | `pop` — tepeden | `dequeue` — baştan |
| Benzetme | Tabak yığını | Market kuyruğu |
| Kullanım | Fonksiyon çağrıları, geri alma, ifade işleme | İş sırası, tampon, genişlik öncelikli arama |

Her ikisinde de erişim **kısıtlıdır**: ortadaki elemana bakamazsınız. Bu kısıt bir eksiklik
değil, doğruluk garantisidir.

## Diziyle yığın

```c
#define KAPASITE 100

typedef struct {
    int veri[KAPASITE];
    int tepe;              /* -1 = bos */
} Yigin;

void baslat(Yigin *y)      { y->tepe = -1; }
int  bosMu(const Yigin *y) { return y->tepe == -1; }
int  doluMu(const Yigin *y){ return y->tepe == KAPASITE - 1; }

int ekle(Yigin *y, int v) {
    if (doluMu(y)) return 0;          /* tasma kontrolu */
    y->veri[++y->tepe] = v;
    return 1;
}

int cikar(Yigin *y, int *v) {
    if (bosMu(y)) return 0;           /* alt tasma kontrolu */
    *v = y->veri[y->tepe--];
    return 1;
}
```

İki kontrol de zorunludur: dolu yığına eklemek dizi sınırını aşar, boş yığından çıkarmak
`veri[-1]` okur. Fonksiyonların başarı/başarısızlık döndürmesi, çağıranın durumu kontrol
etmesini sağlar.

> [!dikkat]
> `y->veri[++y->tepe] = v;` ile `y->veri[y->tepe++] = v;` farklıdır. Tepe -1'den başladığı
> için **önce artırmak** gerekir. Bu iki satırı karıştırmak yığının bir eleman kaymasına
> yol açar.

## Uygulama 1: Parantez denetimi

```c
int dengeliMi(const char *s) {
    Yigin y; baslat(&y);
    for (int i = 0; s[i] != '\0'; i++) {
        if (s[i] == '(') ekle(&y, s[i]);
        else if (s[i] == ')') {
            int t;
            if (!cikar(&y, &t)) return 0;   /* fazladan kapanis */
        }
    }
    return bosMu(&y);                       /* fazladan acilis kaldi mi? */
}
```

İki hata türünü de yakalar: erken kapanış (`())`) ve kapanmamış açılış (`(()`).

## Uygulama 2: Postfix (sonek) hesaplama

`3 4 + 2 *` ifadesi `(3+4)*2 = 14` demektir. Algoritma çok basittir: sayı görürsen yığına
koy, operatör görürsen **iki** sayı çek, işlemi yap, sonucu geri koy.

```c
int b = cikar(); int a = cikar();      /* SIRA ONEMLI: once cekilen SAG operand */
sonuc = a - b;                          /* a / b icin de ayni */
```

Çıkarma ve bölmede sırayı ters yazmak klasik hatadır: `5 3 -` ifadesi 2 vermelidir, -2 değil.

## Dairesel kuyruk

Basit bir kuyrukta `bas` sürekli ilerlerse dizinin başındaki yerler boşa gider. Çözüm,
indeksleri **mod** ile döndürmektir:

```c
#define N 5

typedef struct {
    int veri[N];
    int bas, son, adet;
} Kuyruk;

void baslat(Kuyruk *k) { k->bas = 0; k->son = -1; k->adet = 0; }

int ekle(Kuyruk *k, int v) {
    if (k->adet == N) return 0;
    k->son = (k->son + 1) % N;      /* dolan indeks basa sarar */
    k->veri[k->son] = v;
    k->adet++;
    return 1;
}

int cikar(Kuyruk *k, int *v) {
    if (k->adet == 0) return 0;
    *v = k->veri[k->bas];
    k->bas = (k->bas + 1) % N;
    k->adet--;
    return 1;
}
```

`adet` alanını tutmak, "dolu mu boş mu" ayrımını tek satırda çözer. Yalnızca `bas` ve `son`
ile çalışırsanız `bas == son` durumu hem boşu hem doluyu gösterir ve bir yeri feda etmeniz
gerekir.

## Bağlı listeyle gerçekleştirme

Yığın için başa ekle/baştan çıkar yeterlidir; her ikisi de O(1)'dir ve kapasite sınırı
yoktur. Kuyruk için hem `bas` hem `son` işaretçisi tutulur: baştan çıkarılır, sona eklenir.

> [!sınav]
> En çok sorulan: bir push/pop dizisinin sonunda yığının içeriği; postfix ifadenin değeri;
> dairesel kuyrukta bir dizi işlemden sonra `bas`, `son` ve `adet` değerleri.

