#define KAPASITE 200

/* --- Yigin ile --- */
int palindromYigin(const char *s) {
    char y[KAPASITE];
    int tepe = -1;
    int n = (int)strlen(s);

    if (n > KAPASITE) return -1;        /* kapasite asildi: hata bildir */

    for (int i = 0; i < n; i++)
        y[++tepe] = s[i];               /* hepsini yigina koy */

    for (int i = 0; i < n; i++)
        if (s[i] != y[tepe--]) return 0; /* ters sirayla karsilastir */

    return 1;
}

/* --- Yiginsiz: iki indeks --- */
int palindromIndeks(const char *s) {
    int bas = 0, son = (int)strlen(s) - 1;

    while (bas < son) {
        if (s[bas] != s[son]) return 0;
        bas++;
        son--;
    }
    return 1;                            /* bos ve tek karakterli metin de palindromdur */
}

int main(void) {
    const char *t[4] = {"kayak", "merhaba", "aa", ""};

    for (int i = 0; i < 4; i++)
        printf("%d %d\n", palindromYigin(t[i]), palindromIndeks(t[i]));
    /* 1 1 / 0 0 / 1 1 / 1 1 */
    return 0;
}
