/* ================= liste.c ================= */
#include "liste.h"
#include <stdio.h>
#include <stdlib.h>

/* Sadece bu dosyada kullanilan yardimci: disariya acilmaz */
static Dugum *dugumYarat(int v, Dugum *sonraki) {
    Dugum *yeni = malloc(sizeof(*yeni));
    if (yeni == NULL) return NULL;
    yeni->veri = v;
    yeni->sonraki = sonraki;
    return yeni;
}

Dugum *basaEkle(Dugum *bas, int v) {
    Dugum *yeni = dugumYarat(v, bas);
    return (yeni == NULL) ? bas : yeni;
}

int uzunluk(const Dugum *bas) {
    int n = 0;
    for (const Dugum *p = bas; p != NULL; p = p->sonraki) n++;
    return n;
}

void yazdir(const Dugum *bas) {
    for (const Dugum *p = bas; p != NULL; p = p->sonraki)
        printf("%d%s", p->veri, p->sonraki ? " " : "\n");
}

void bosalt(Dugum *bas) {
    while (bas != NULL) {
        Dugum *t = bas;
        bas = bas->sonraki;
        free(t);
    }
}
```

